contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public {
        bool before = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        bool reverted;
        bool ret;
        c.logSetupFailed(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        if (!reverted) {
            ret = c.approvedToLog(caller);
        }

        bool afterStatus = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        assert(!reverted && ret == before && afterStatus == before);
    }

    receive() external payable {}
}

